const wd="/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild";
const [zar1,zar2,search1,search2,search3]=await Promise.all([
  tools.exec_command({cmd:"sed -n '55,120p' AlgebraicJacobian/Picard/DivisorFamilyZar.lean",workdir:wd,yield_time_ms:10000,max_output_tokens:12000}),
  tools.exec_command({cmd:"sed -n '210,295p' AlgebraicJacobian/Picard/DivisorFamilyZar.lean",workdir:wd,yield_time_ms:10000,max_output_tokens:16000}),
