];
const rs=await Promise.all(qs.map(async q=>({q,r:await tools.mcp__lean_lsp__lean_local_search({query:q,project_root:"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",limit:50})})));
for(const x of rs) text(`--- ${x.q} ---\n${JSON.stringify(x.r)}`);

